log_info() { printf '  [•] %s\n' "$*"; [[ $LOG_ENABLED == 0 ]] || printf '%s INFO %s\n' "$(date -Is)" "$*" >> "$LOG"; }
log_ok() { printf '  [✓] %s\n' "$*"; [[ $LOG_ENABLED == 0 ]] || printf '%s OK %s\n' "$(date -Is)" "$*" >> "$LOG"; }
log_warn() { printf '  [!] %s\n' "$*"; [[ $LOG_ENABLED == 0 ]] || printf '%s WARN %s\n' "$(date -Is)" "$*" >> "$LOG"; }
log_error() { printf '  [✗] %s\n' "$*" >&2; [[ $LOG_ENABLED == 0 ]] || printf '%s ERROR %s\n' "$(date -Is)" "$*" >> "$LOG"; }
die() { local rc=$1; shift; log_error "$*"; exit "$rc"; }
ask_yes() {
    local answer
    [[ -r /dev/tty && -w /dev/tty ]] || return 1
    printf '\n  %s [Д/Н; Enter — Н]: ' "$1" > /dev/tty
    IFS= read -r answer < /dev/tty || return 1
    case "$answer" in Д|д|Да|да|ДА|y|Y|yes|YES) return 0;; *) return 1;; esac
}
prompt() {
    local name=$1 title=$2 default=${3:-} value
    [[ -r /dev/tty ]] || die 1 "Требуется параметр $name для неинтерактивного запуска."
    printf '  %s [%s]: ' "$title" "$default" > /dev/tty
    IFS= read -r value < /dev/tty || die 1 'Ввод прерван.'
    printf -v "$name" '%s' "${value:-$default}"
}
banner() {
    printf '\n══════════════════════════════════════════════════\n  Nuvrion XHTTP Installer · v%s\n  Автор: Nuvrion · nuvrion-kvn\n══════════════════════════════════════════════════\n' "$INSTALLER_VERSION"
    printf '  Reality TCP + XHTTP · PokéHabitat\n  Д = Да · Н = Нет\n\n'
}
require_root() { (( EUID == 0 )) || die 1 'Запустите от root.'; }
detect_os() {
    # shellcheck disable=SC1091
    source /etc/os-release
    log_info "ОС: ${PRETTY_NAME:-unknown}; ядро: $(uname -r); uptime: $(uptime -p)"
    [[ $ACTION == diagnose ]] || { [[ ${ID:-} == ubuntu && ${VERSION_ID:-} == 24.04 ]] || die 2 'Поддерживается Ubuntu 24.04/24.04.x.'; }
    command -v python3 >/dev/null || die 1 'Требуется системный python3 (входит в Ubuntu 24.04).'
}

